const jobs = [
  {
    brand: 'dax-collective',
    agentId: 'dax_collective_parent_hub_video_agent',
    title: 'What The Dax Collective Is Building This Year',
    script: 'The Dax Collective is the home base for travel, anime, faith, and creative systems. This is where the brands connect, the ideas get built, and the community sees the full story. Start here, then choose the brand that speaks to you first.',
    cta: 'Explore every Dax Collective brand.',
    tags: ['dax collective', 'creator hub', 'brand launch']
  },
  {
    brand: 'dax-the-traveler',
    agentId: 'dax_the_traveler_video_agent',
    title: 'A Realistic First Day Travel Reset',
    script: 'Do not try to conquer a new city on day one. Pick one walkable area, one easy meal, one grocery stop, and one calm activity. The first day is for orientation, not performance. Once the city feels usable, the real adventure starts.',
    cta: 'Save this for your next arrival day.',
    tags: ['travel', 'solo travel', 'arrival day']
  },
  {
    brand: 'time-zone-travelers',
    agentId: 'time_zone_travelers_video_agent',
    title: 'The Carry-On Rule For Remote Work Travel',
    script: 'Every item in your carry-on should solve a travel problem or a work problem. If it does neither, it stays home. Build around power, laundry, layers, and the time-zone reset day. That is how you keep the trip light and the workday protected.',
    cta: 'Save the remote-work packing checklist.',
    tags: ['travel hacks', 'remote work', 'packing']
  },
  {
    brand: 'ani-dax',
    agentId: 'ani_dax_video_agent',
    title: 'Why Character Choices Matter More Than Power Levels',
    script: 'Power scaling is fun, but character choices are what make an anime stay with you. The best moments are not always the biggest attacks. Sometimes they are the decision that reveals who a character really is.',
    cta: 'Comment the anime decision that changed everything for you.',
    tags: ['anime', 'anime analysis', 'ani dax']
  },
  {
    brand: 'gods-vessel',
    agentId: 'gods_vessel_video_agent',
    title: 'One Small Faithful Step Today',
    script: 'Faith does not always start with a loud breakthrough. Some days it starts with one honest prayer, one verse, one kind message, or one step back toward peace. Small obedience still counts.',
    cta: 'Send this to someone who needs a steady reminder.',
    tags: ['faith', 'encouragement', 'gods vessel']
  }
];

return jobs.map((job) => ({
  json: {
    ...job,
    videoServiceUrl: 'http://host.docker.internal:3001/create-video',
    durationSeconds: 18,
    scenes: ['Hook', 'Core idea', 'Practical takeaway', 'CTA'],
    publishAllowed: false,
    reviewStatus: 'manual_review_required',
    notes: 'Local review video only. No upload or public publishing.'
  }
}));

const sourceItems = $('Build Brand Video Jobs').all();
const resultItems = $input.all();

return resultItems.map((item, index) => {
  const source = sourceItems[index]?.json || {};
  const result = item.json || {};
  return {
    json: {
      agentId: source.agentId,
      brand: source.brand,
      title: source.title,
      status: result.ok ? 'video_ready' : 'needs_repair',
      reviewStatus: 'manual_review_required',
      publishAllowed: false,
      outputPath: result.outputPath || '',
      metadataPath: result.metadataPath || '',
      qaChecks: ['brand_voice', 'hook_present', 'cta_present', 'manual_review_required', 'no_public_upload'],
      notes: 'Review the MP4 and metadata before any publishing workflow is enabled.',
      createdAt: new Date().toISOString()
    }
  };
});
